-- FK 순서로 기존 시드 제거
DELETE FROM reviews WHERE id BETWEEN 90001 AND 90050;
DELETE FROM reservations WHERE id BETWEEN 90001 AND 90050;
DELETE FROM members WHERE id BETWEEN 9001 AND 9020;

