INSERT INTO reviews (id,member_id,reservation_id,rating,comment,created_at,updated_at) VALUES
(90001,9001,90001,4,'사진보다 실물이 훨씬 좋았어요. 호스트님이 체크인 안내도 친절하게 해주셔서 편하게 머물렀습니다.','2026-06-08 03:00:00','2026-06-08 03:00:00'),
(90002,9002,90002,5,'위치가 정말 좋아요. 주변에 맛집과 카페가 많아서 걸어다니기 편했습니다. 다음에 또 오고 싶어요.','2026-06-03 03:00:00','2026-06-03 03:00:00'),
(90003,9003,90003,5,'청소 상태가 아주 깨끗했고 침구도 보송보송했어요. 가족 여행으로 다녀왔는데 모두 만족했습니다.','2026-05-29 03:00:00','2026-05-29 03:00:00'),
(90004,9004,90004,5,'조용하고 아늑한 공간이라 푹 쉬다 갑니다. 사진에서 본 그대로라 기대 이상이었어요.','2026-05-24 03:00:00','2026-05-24 03:00:00'),
(90005,9005,90005,5,'가성비가 정말 좋습니다. 넓은 거실과 깔끔한 주방 덕분에 편하게 요리도 해먹었어요.','2026-05-19 03:00:00','2026-05-19 03:00:00'),
(90006,9006,90006,5,'뷰가 환상적이었어요. 아침에 커피 한잔하면서 보는 풍경이 잊히지 않네요.','2026-05-14 03:00:00','2026-05-14 03:00:00'),
(90007,9007,90007,5,'호스트님 응답이 빨라서 소통이 편했습니다. 필요한 물품도 다 갖춰져 있어서 좋았어요.','2026-05-09 03:00:00','2026-05-09 03:00:00'),
(90008,9008,90008,5,'주차가 편리해서 차로 이동하기 좋았어요. 짐 옮기기도 수월했습니다.','2026-05-04 03:00:00','2026-05-04 03:00:00'),
(90009,9009,90009,5,'인테리어가 감각적이라 사진 찍기 좋았어요. 친구들과 즐거운 시간 보냈습니다.','2026-04-29 03:00:00','2026-04-29 03:00:00'),
(90010,9010,90010,4,'체크인 체크아웃이 간편했고 안내가 자세해서 처음 이용하는데도 헤매지 않았어요.','2026-04-24 03:00:00','2026-04-24 03:00:00'),
(90011,9011,90011,5,'침대가 정말 편했어요. 오랜만에 푹 자고 갑니다. 다음에도 꼭 재방문할게요.','2026-04-19 03:00:00','2026-04-19 03:00:00'),
(90012,9012,90012,5,'주변이 한적해서 휴식하기 딱 좋았습니다. 반려동물과 함께 와도 좋을 것 같아요.','2026-04-14 03:00:00','2026-04-14 03:00:00'),
(90013,9013,90013,5,'온수도 잘 나오고 난방도 따뜻했어요. 겨울 여행이었는데 전혀 춥지 않았습니다.','2026-04-09 03:00:00','2026-04-09 03:00:00'),
(90014,9014,90014,5,'공간이 넓어서 여러 명이 묵기에도 충분했어요. 단체 모임 장소로 추천합니다.','2026-04-04 03:00:00','2026-04-04 03:00:00'),
(90015,9015,90015,5,'깔끔하고 모던한 숙소였어요. 작은 디테일까지 신경 쓰신 게 느껴졌습니다.','2026-03-30 03:00:00','2026-03-30 03:00:00'),
(90016,9016,90016,5,'대중교통 접근성이 좋아서 차 없이도 이동이 편했어요. 역에서 가까운 게 큰 장점입니다.','2026-03-25 03:00:00','2026-03-25 03:00:00'),
(90017,9017,90017,5,'사장님이 추천해주신 근처 식당이 다 맛집이었어요. 덕분에 알찬 여행이 됐습니다.','2026-03-20 03:00:00','2026-03-20 03:00:00'),
(90018,9018,90018,5,'조명이 분위기 있어서 저녁에 더 아늑했어요. 휴식하기 정말 좋은 공간입니다.','2026-03-15 03:00:00','2026-03-15 03:00:00'),
(90019,9019,90019,4,'욕실이 넓고 깨끗했어요. 어메니티도 잘 구비되어 있어서 따로 챙길 게 없었습니다.','2026-03-10 03:00:00','2026-03-10 03:00:00'),
(90020,9020,90020,5,'전체적으로 만족스러운 숙박이었어요. 가격 대비 시설과 위치 모두 훌륭합니다.','2026-03-05 03:00:00','2026-03-05 03:00:00'),
(90021,9001,90021,5,'약간 찾아가기 어려웠지만 도착하니 만족스러웠어요. 안내를 조금 더 자세히 해주시면 좋겠습니다.','2026-02-28 03:00:00','2026-02-28 03:00:00'),
(90022,9002,90022,5,'대체로 좋았는데 주변이 살짝 시끄러운 편이었어요. 그래도 시설은 깔끔했습니다.','2026-02-23 03:00:00','2026-02-23 03:00:00'),
(90023,9003,90023,5,'사진보다 실물이 훨씬 좋았어요. 호스트님이 체크인 안내도 친절하게 해주셔서 편하게 머물렀습니다.','2026-02-18 03:00:00','2026-02-18 03:00:00'),
